/**
 * What a Session is doing, read from what happened and never from what the agent said. One answer,
 * for every surface that draws a Session: the Sessions list, the Cockpit's tiles, lanes and calls.
 */
export type SessionStanding =
  /** A turn is running. */
  | "working"
  /** A turn is running and nothing has happened for the quiet threshold. */
  | "stuck"
  /**
   * The turn ended on a message of the agent's that only reports, and the person has not answered
   * since. Under Idle: it is the unread mark, and raises no item. One that asks is an item instead.
   */
  | "replied"
  /** Nothing runs and nothing is asked, and nothing that excuses a stop stands. `SessionRecord::stopped` says why. */
  | "stopped"
  /** The agent said, through `all_done`, that nothing is left, and the person has not answered. */
  | "done"
  /** Nothing is owed. What a `done` becomes once the person dismisses it. */
  | "idle";

/** Why a Job stopped, read from what Fleet saw. */
export type StopReason =
  /** It ended its turn with nothing running and nothing asked, and stopped again after it was told. */
  | "turn_ended"
  /** As `TurnEnded`, with tasks still open on its list. */
  | "tasks_open"
  /** Its process ended during a turn and starting it again did not bring it back. */
  | "process_gone"
  /** As `ProcessGone`, and the process ended while Fleet was not running. */
  | "fleet_down";

/** Where Fleet stands on starting a stopped Job's process again. */
export type StopRestart =
  /** Nothing to start: its process did not end. */
  | "none"
  | "queued"
  | "running"
  | "failed";

/** Where a repair Job stands, once a restart failed. */
export type StopRepair =
  | "running"
  | "failed"
  /** Fleet is unhealthy, so it started none. */
  | "held";

/** A stretch Fleet was not running. */
export type FleetAway = {
  from: Instant;
  to: Instant;
};

/**
 * A Job that is not running and was not parked: why, since when, and what Fleet is doing about it.
 * **Raises no item**: the mark and, once Fleet has run out of things to try, the call reach the person.
 */
export type SessionStopped = {
  reason: StopReason;
  at: Instant;
  /** With `tasks_open`: the tasks still open. */
  tasks?: string[];
  /** With `process_gone`: the last thing the process said. */
  said?: string;
  restart: StopRestart;
  repair?: StopRepair;
  /** Fleet has run out of things to try: only the person moves it now. */
  gave_up?: boolean;
  /** With `fleet_down`: the stretch Fleet was not running. */
  down?: FleetAway;
};

/**
 * The repair Fleet is running on a Job, whatever state the Job is in. `said` is Fleet's own words for what
 * broke, such as `a command hung`, so no client spells them. `docs/concepts/session/what-a-job-is-doing.md`.
 */
export type SessionRepairing = {
  said: string;
  since: Instant;
};

/** One thing a session is waiting on the person for. */
export type WaitingItem = {
  /**
   * Stable across updates: the agent's own, or `ask:<call>`, `walk:<url>`, `perm:<call>`,
   * `window_ask:<row>`, `draft:<row>`, `unsent:<session>`, `done:<done_since>`.
   */
  id: string;
  text: string;
  /** When it began to wait. */
  since: Instant;
  source: WaitingSource;
  act?: WaitingAct;
  /** Present only on an `answer` item that has choices. */
  options?: WaitingOption[];
  /**
   * An agent item asking for his approval: its options are Fleet's, *Approve* then *Ask for
   * changes*, and his Approve closes the plan's first open `you_approved` gate. Absent where false.
   */
  approves?: boolean;
  /** The procedure the person follows, in order; its press opens them as steps. */
  steps?: string[];
  /** Where a question asked in the walk window points. Present only on a `window_ask` item. */
  place?: WindowPlace;
  /** A `replied` item whose sentence he said is a question (`confirm_waiting`). Absent where he has not. */
  confirmed?: boolean;
  /**
   * On a `slot_choice` item only: the slots a Job Fleet hosts holds, longest quiet first, each
   * with why Free is off where it is. Absent where Fleet has read none yet and where a terminal
   * or a person holds every slot, and the call then reads as two choices and no rows.
   */
  holders?: SlotHolder[];
  /**
   * On a `slot_choice` item only: when Fleet began making the slot *Add a slot* asked for. While it
   * is present the Job's call stays on the list for the person to see the wait, and asks for nothing.
   */
  creating_since?: Instant;
  /**
   * On a `slot_choice` item only: why the last slot Fleet tried to make was not made. Gone the next
   * time *Add a slot* is answered.
   */
  create_refused?: string;
  /**
   * On a question or a card, where the Answer role stands at Suggest: what the Operator read and
   * the option it would pick. His press on that option is the one press. Absent otherwise.
   */
  operator_read?: OperatorRead;
  /**
   * The id of one of the Job's artifacts this item is about, for a client to name and open: an agent's item's
   * from `WaitingInput::artifact`, and a sketch's, a draft's or a page's own. Absent otherwise.
   */
  artifact?: string;
  /**
   * Its place among the Job's open asks, 1 first: the Job's own order from `order_waiting`, else Fleet's
   * fallback. 0 on a list that is not a Job's open asks, such as the closed ones. `docs/concepts/session/waiting-on-the-person.md`.
   */
  order?: number;
  /** Why it stands where it does, one plain sentence: the Job's own, else Fleet's. Empty where `order` is 0. */
  why?: string;
};

/** What the Operator made of a question it would answer. */
export type OperatorRead = {
  /** Why, in the call's words. */
  read: string;
  /** The option it would pick, in its words. */
  pick: string;
};

/**
 * A follow-up the agent said it keeps for itself, read from the close of a reply and open until it is
 * settled. The same sentence said again is the same one.
 */
export type SessionLater = {
  /** What `settle_later` names it by. */
  id: string;
  /** As the agent said it. */
  sentence: string;
  /** When the reply that said it ended. */
  said_at: Instant;
  /** He said it is a follow-up, with thumbs up (`confirm_later`). Absent where he has not. */
  confirmed?: boolean;
};

/** How the agent is told to settle an item itself. */
export type WaitingMode =
  /** Think it through and decide. */
  | "best"
  /** Just get it done: finish the work and land it, skipping the formalities. */
  | "quick";

/**
 * `answer_waiting`: the person settles one item. `choice` is an index into the item's `options`, `text`
 * is their own words, and `mode` leaves it to the agent.
 */
export type AnswerWaiting = {
  session_id: SessionId;
  item_id: string;
  choice?: number;
  text?: string;
  mode?: WaitingMode;
  /**
   * The person's corrected text for a `draft` item, which approves it with their words. Refused on
   * an item of any other source.
   */
  fixed?: string;
  /** Pictures and tags that go with `text`, sent to the agent as a message's are. */
  extras?: AnswerExtras;
};

/**
 * `dismiss_waiting`: the person drops one item for good. An item the agent stated tells it so;
 * one Fleet derived is only dropped.
 */
export type DismissWaiting = {
  session_id: SessionId;
  item_id: string;
  /** Why he removed it, sent to the agent after the item where it is non-blank. Absent where he gave none. */
  reason?: string;
  /**
   * He pressed Not a question on an item Fleet read from a reply: its sentence is kept as one that
   * asks nothing. Refused on an item of any other source. Absent where false.
   */
  misread?: boolean;
};

/** An item the person closed, as the Job's record lists it. Fleet kept the item whole when it was closed. */
export type ClosedWaiting = {
  /** The item as Needs you drew it when it was closed. Its `id` is what `reopen_waiting` takes. */
  item: WaitingItem;
  /** When it was closed. */
  at: Instant;
  /**
   * What it stood for has ended, so it cannot be reopened: a permission whose call ended, a walk that
   * was withdrawn, any item of a Job that has ended. The agent's own item is reopenable while the Job
   * lives. Absent where false.
   */
  ended?: boolean;
};

/** One row of the ledger as the wire carries it. */
export type Attachment = {
  kind: string;
  /**
   * The repository a slot or a branch is of; absent where it is of none
   * Fleet serves.
   */
  manifest_id?: ManifestId;
  target: string;
  state: AttachmentState;
  detail?: Record<string, string>;
  since: Instant;
  changed_at: Instant;
};

/** A piece of Armada a hosted session's agent came up without. */
export type ToolMissing =
  /** The `armada` mod was not among the plugins the CLI loaded. */
  | "mod"
  /** Fleet's door was not among the MCP servers, or not connected. */
  | "door"
  /** The CLI served no task list tools. */
  | "task_tools";

/** What kind of work a Job's agent left running past its turn. */
export type RunningKind =
  | "subagent"
  | "background_task";

/**
 * One subagent or background task a hosted Job's agent left working past its turn. **A turn
 * `idle` with one of these is not a Job with nothing running**: ending its process takes the work
 * with it.
 */
export type RunningWork = {
  kind: RunningKind;
  /** What it is: the subagent's description or the task's own title, else its target. */
  what: string;
  /** When it began. */
  since: Instant;
};

/**
 * What a hosted session's agent lacks of Armada's own, and the CLI version that lacked it. **Never
 * empty**: a session missing nothing carries none.
 */
export type ToolsMissing = {
  /** The harness's own name, so a client names the CLI without spelling it. */
  harness: string;
  /** The command that updates the CLI, which a client runs in the session's terminal. */
  update: string;
  harness_version: string;
  missing: ToolMissing[];
};

/** One thing, not the person, that keeps a Job open: a fact, never a sentence. */
export type HeldOpenBy =
  /** A live watch of the Job, by its name. */
  | {
      kind: "watch";
      name: string;
    }
  /** A Job it started that is still running, by its title. */
  | {
      kind: "job";
      name: string;
    }
  /** A pull request of its own that is open and whose Checks have not failed. */
  | {
      kind: "pull_request";
      number: number;
      on: PullRequestWait;
    };

/** What an open pull request waits on. */
export type PullRequestWait =
  /** In the base branch's merge queue. */
  | {
      kind: "queue";
    }
  /** Auto-merge is on and its Checks have passed or are not yet read. */
  | {
      kind: "auto_merge";
    }
  /** Its Checks are running; `auto_merge` says it merges once they pass. */
  | {
      kind: "checks";
      auto_merge: boolean;
    };

/**
 * A session and everything it holds. Answered by `report_session`, listed by
 * `list_sessions`, and published whole as `session.changed`, so a client
 * replaces the row rather than patching it.
 */
export type SessionRecord = {
  id: SessionId;
  /** The id of the paired Mac that holds this Job. **Absent means held by this Mac.** */
  mac?: string;
  harness: string;
  origin: SessionOrigin;
  manifest_id?: ManifestId;
  cwd: string;
  title?: string;
  state: SessionState;
  started_at: Instant;
  last_seen_at: Instant;
  last_turn_at?: Instant;
  ended_at?: Instant;
  end_reason?: string;
  usage: SessionUsage;
  attachments: Attachment[];
  /**
   * What a session Bridge hosts carries beyond a terminal's. Absent on one
   * a harness reports. Since 23.49.
   */
  hosted?: HostedFacts;
  /** What a session run in a terminal runs on, once its mod has said. Since 23.53. */
  terminal?: TerminalFacts;
  /**
   * A session run in a terminal whose `armada` mod is older than the one the repository holds,
   * or reported no version at all. Absent otherwise, and where Fleet cannot read the
   * repository's. Since 23.62.
   */
  mod_out_of_date?: boolean;
  /**
   * The version its `armada` mod last reported, on a session of either origin. Absent until a mod
   * has reported one, which is how a session whose mod never loaded is told from one whose mod did.
   */
  mod_version?: string;
  /**
   * A hosted session whose agent came up without some of its Armada pieces, as Fleet read the CLI's
   * first line of the process. Absent when nothing is missing, on a session a terminal runs and once
   * the session ends. Held in memory: a Fleet that restarts has none until the next turn starts.
   */
  tools_missing?: ToolsMissing;
  /**
   * The subagents and background tasks a hosted session's agent has working past its turn, with a
   * live process and inside the hour Fleet gives work that shows nothing. Empty where none is.
   */
  running?: RunningWork[];
  /**
   * What the session waits on the person for: the agent's list with Fleet's own items merged in, the
   * agent's first. Empty for an ended session.
   */
  waiting_for?: WaitingItem[];
  /**
   * When the agent said, through `all_done`, that it has nothing left to work on. Cleared by the
   * person's next message, by a non-empty `waiting_for`, and by a hosted turn starting again.
   */
  done_since?: Instant;
  /** What the agent said the Job achieved, given with `all_done`. Stands and clears with `done_since`. */
  done_summary?: string;
  /**
   * A hosted Job's running summary of what it has done, one or two sentences a small model
   * rewrites when a turn ends and when a call goes to the person. Absent until one is written,
   * and for a Job run in a terminal.
   */
  so_far?: string;
  /**
   * What the Session is doing, derived by Fleet on every read from its turn, its thread and
   * `done_since`. Absent from a Fleet that predates it, and Bridge then draws the Session as it
   * drew it before. Since 23.86.
   */
  standing?: SessionStanding;
  /**
   * The plan's limit stopped this session, and Fleet wakes it with `Continue` a minute after this
   * instant, when the limit has reset. Cleared by a turn, a message from the person, the wake
   * and the session ending. Absent on a session that is not held.
   */
  held_until?: Instant;
  /**
   * The person snoozed this Job until this instant. The snooze paused it, and what it raised stays
   * on it with no push, card, banner or sound until then, when it is resumed. Cleared when the time comes and by
   * `snooze_session` with no `until`; kept through ending, pausing and a repair. Absent on a Job
   * that is not snoozed.
   */
  snoozed_until?: Instant;
  /**
   * The person's one prioritised Job, set and cleared by `prioritise_session`: a loaded machine
   * runs its builds while other Jobs' wait. At most one live Job carries it; absent on every
   * other, and on an ended Job.
   */
  prioritised?: boolean;
  /**
   * What fills the session's context window, as `/context` shows it, from the latest report. Absent
   * until a mod reports one.
   */
  context_breakdown?: ContextBreakdown;
  /**
   * The Loadout in brief, from the latest `equipped` and the latest turn's uses. Absent where no
   * `equipped` was ever reported. The whole of it is `get_session_loadout`.
   */
  loadout_summary?: LoadoutSummary;
  /**
   * This Job was started on your words: it may call what only a Job on your words may. Absent
   * on every other session.
   */
  on_your_words?: boolean;
  /** A Mod Job, started from Mod for modding Armada itself. Absent on every other session. */
  mod?: boolean;
  /** The Job whose panes hold the Custom tab this Mod Job builds, and the tab's id there, as the start carried them. Absent on every other session. */
  from_job?: string;
  from_tab?: string;
  /** A Mod Job started with the aim `instrument`, so it builds an instrument for a bay of the console. Absent on every other session. */
  mod_of_bay?: boolean;
  /**
   * A Side Job, started by `start_side_job`: it opens onto its terminal `t1`, and its agent
   * runs nothing until the person writes. Absent on every other session.
   */
  side_job?: boolean;
  /**
   * The Operator's own session: one per Mac, hosted with no repository, no slot and no Manifest, which
   * Bridge keeps out of the Jobs list. Absent on every other session.
   */
  operator?: boolean;
  /**
   * Auto land is on: Fleet turns on the forge's auto-merge for each pull request the Session
   * holds as it attaches, and off again when this is turned off. Absent is off. Hosted only.
   */
  auto_land?: boolean;
  /**
   * What a hosted session is doing, as Fleet's gate saw its tool calls. Absent before the first
   * call, on a session a terminal runs and once the session ends. Since 14 Oct 2026.
   */
  activity?: SessionActivity;
  /**
   * What the Session has built, derived by Fleet on every read. Absent for a Session that has done
   * nothing Fleet observed. `docs/concepts/session.md`, *The build record*.
   */
  build?: SessionBuild;
  /**
   * The workflow id the Session runs under. Absent is a custom Session, which is not a default
   * workflow. Hosted Sessions only. Since 23.91. `docs/concepts/session.md`, *A Session's proposal*.
   */
  workflow?: string;
  /** What the proposer did for this Session. Absent where it was never asked. Since 23.91. */
  proposal?: SessionProposal;
  /**
   * The plan the agent recorded, with what Fleet saw of it carried out. Absent until it records
   * one. `docs/concepts/session.md`, *The plan*.
   */
  plan?: SessionPlan;
  /**
   * The latest files the Session and its subagents wrote, newest last, for the Field. Absent
   * until one is seen.
   */
  touches?: FileTouch[];
  /**
   * The index of the workflow step the Session is on, read by Fleet from what it observed and never
   * from the agent's word. Absent for a custom Session, and once the delivering step's pull request
   * has merged with no step after it. `docs/concepts/session.md`, *The rail*.
   */
  workflow_step?: number;
  /**
   * The Judge's readings of this Job's artifacts, one per artifact with the latest replacing the one
   * before, oldest asked first. Absent until a Judge was asked. `docs/practices/protocol/a-job-is-judged-on-demand.md`.
   */
  judge_readings?: JudgeReading[];
  /**
   * The items the person closed from `waiting_for`, newest first, each kept whole at the moment he did.
   * A bounded window. Since 29 Oct 2026.
   */
  closed?: ClosedWaiting[];
  /**
   * His answers to the Job's asks, oldest first: each ask's question, how he answered and his words, apart
   * from what the Job was told. The thread card of an answered ask draws its answer from here. Since 20 Nov 2026.
   */
  answers?: AnsweredAsk[];
  /**
   * Dispatched to wait on another Session and not started: it holds its brief, no slot and no
   * process until the condition is met. Absent once it has started, and on a Session that never
   * waited. `docs/concepts/session.md`, *A Session that waits on another*.
   */
  waits?: SessionWait;
  /**
   * The follow-ups the agent said it keeps for itself, each open until it is settled, oldest first.
   * `all_done` is refused while any is open.
   */
  later?: SessionLater[];
  /**
   * Everything that is not the person that keeps the Job open, in the order it reads: each live watch
   * in the order it started, then each of its own pull requests in the queue, set to merge or on its
   * Checks. Set only once its turn has ended and nothing is in `waiting_for`. Empty otherwise. Not a Needs
   * you item. `docs/design/fleet-watches-ci-and-deploys-for-a-job.md`.
   */
  held_open_by?: HeldOpenBy[];
  /**
   * Waiting for a worktree slot: in its repository's line, or its `armada worktree lease` asking.
   * Absent otherwise. Since 14 Nov 2026, in place of the `slot_choice` item.
   */
  slot_wait?: SlotWait;
  /** Why it stopped, with `standing` `stopped`. Absent otherwise. */
  stopped?: SessionStopped;
  /** The repair Fleet is running on it now, in any state. Absent while none runs. */
  repairing?: SessionRepairing;
  /** When Fleet tells it to carry on, while a stop nothing excuses has not been told about. Absent otherwise. */
  stop_told_by?: Instant;
  /** When the turn running now began. Absent between turns. */
  turn_since?: Instant;
  /** The last time Fleet heard anything from the running turn. Absent between turns. */
  last_heard_at?: Instant;
  /**
   * How the Job was started, as it stood when its process first ran, so a later change of model,
   * effort or mode does not rewrite it. Absent for a Job started before Fleet kept it, and for a
   * terminal session.
   */
  started?: SessionStarted;
  /**
   * When each step of the workflow began, oldest first. A step the Job went back to appears again.
   * Empty for a custom Session and for one that has entered no step.
   */
  workflow_visits?: StepVisit[];
  /**
   * The steps the person skipped, by the index `workflow_step` uses, ascending. The rail counts each
   * one passed. Empty where none is. `skip_session_step`.
   */
  skipped_steps?: number[];
  /**
   * What the step the Job is on waits for, as the rail words it: `Waiting on PR #812: Approved`. One
   * sentence for each lifecycle end the step lists that has not come, in the order the step lists them.
   * Empty where the step waits on no lifecycle, and once an end has come. Since 30 Oct 2026.
   */
  workflow_waiting_on?: string[];
  /**
   * The step the Job is on as the column draws it: its tabs, usual time, what ends it, whether it is
   * stalled, and the steps passed without the Approve they wait on. Absent for a Job that follows no
   * workflow, one that has ended, and one whose workflow did not resolve. Since 20 Nov 2026.
   */
  workflow_strip?: WorkflowStrip;
  /**
   * The Job's own copy of its workflow, once a step of it was changed: the steps the rail and the lanes
   * draw, in place of the ones the repository's definition lists. Also the steps a publish pinned the Job to
   * (`docs/practices/protocol/protocol-23-97-moving-running-jobs-to-a-new-workflow-version.md`). Absent for a Job with neither.
   * Since 30 Oct 2026. `change_session_steps`.
   */
  workflow_copy?: WorkflowSummary;
  /**
   * What the Job still holds that End job lists: each lifecycle instance neither ended by ending or
   * handing away the Job nor in an end state of its lifecycle, in the order it was taken on. One
   * standing in no state is listed too. Set for a live Job only; empty for one that holds nothing and
   * for one that has ended. Since 9 Nov 2026. `docs/practices/protocol/a-jobs-in-flight-list.md`.
   */
  in_flight?: InFlight[];
  /**
   * The state the Job's row in a Jobs list draws: mark, lamp and group, without words. Absent where
   * Fleet did not read one. Since 9 Nov 2026. `docs/practices/protocol/a-jobs-row-mark.md`.
   */
  mark?: JobMark;
  /**
   * The last instant the person was in the Job, as a client told it by `view_session`: when it came on
   * screen or when it left. Absent where he never was. Since 9 Nov 2026.
   */
  viewed_at?: Instant;
  /**
   * Whether Compact is offered on the Job, or off and why, without words. Absent where Fleet did
   * not read one. Since 9 Nov 2026. `docs/practices/protocol/the-title-bars-views-fleet-reads.md`.
   */
  compact?: CompactOffer;
  /**
   * The Job's lanes, worked out by Fleet: where it stands in its workflow, what it holds and the lanes
   * and edges drawn from both. Set for a live Job that holds an instance or follows a workflow; absent
   * for one that has ended and for one that does neither. Since 11 Nov 2026.
   * `docs/practices/protocol/a-jobs-lanes-fleet-works-out.md`.
   */
  lanes?: JobLanesView;
  /**
   * The pull request descriptions this Job proposed that wait on the person, each with the pull
   * request it is for. A `draft` row finds its pull request here by `draft`, and a `pr` row its
   * draft by repository and number. Empty where none waits. Since 12 Nov 2026.
   * `docs/practices/protocol/a-draft-names-the-pull-request-it-describes.md`.
   */
  pull_request_drafts?: PullRequestDraft[];
  /**
   * Each tracker item the Job waits on because another holds it, in the item's order. Empty where it
   * waits on none. Since 14 Nov 2026. `docs/practices/protocol/a-jobs-wait-on-a-held-item.md`.
   */
  claim_waits?: ClaimWait[];
  /**
   * Each clash this Job is one of two in: files both write, raised with `raise_conflict` or settled with
   * `settle_clash`, the same on the other Job's record. Empty where it has none. Since 27 Nov 2026.
   * `docs/concepts/fleet.md`, *Claims a Job holds*.
   */
  clashes?: JobClash[];
  /**
   * Whether the Job holds claims its project's store has not taken yet, because the store did not
   * answer. Fleet sends them when it does. Absent where all are sent. Since 14 Nov 2026.
   */
  claims_unsent?: boolean;
  /**
   * Whether a reply of the Job's answers a question of his that he has not read yet, for the dot on the Job's row.
   * `list_job_questions` names which. Absent where none waits. Since 17 Nov 2026. `docs/concepts/job-story.md`.
   */
  answer_unread?: boolean;
  /**
   * The features the Job writes to now: each feature of a library it filed a written file under, once, in the library's
   * order, while it is live and holds a slot. The Jobs list groups by feature and by area from these. Empty for a Job that
   * writes to none and for one that has ended. Since 27 Nov 2026.
   */
  features?: SessionFeature[];
};

/** A feature a Job writes to, with enough of its library to draw its heading and its area's. */
export type SessionFeature = {
  /** The project whose library holds it, by id. */
  project: string;
  slug: string;
  title: string;
  /** The slug of its area, and the area's title. */
  area: string;
  area_title: string;
  /** Its area's place in the library and its own place in the area, so headings stand in the library's order. */
  area_place: number;
  place: number;
};

/**
 * A tracker item a Job waits on: another Job holds its claim in the project's store, or a person is
 * its assignee in beads. Or a failing test another Job is fixing, which threw its pull request out
 * of the merge queue. The Job's wait line. Since 14 Nov 2026.
 */
export type ClaimWait = {
  /** The item as its tracker names it: `armada-zasx.3`, `12`. */
  item: string;
  /**
   * The person holding it: the holding Job's forge login, or the assignee in beads. Empty where the
   * store named none.
   */
  holder: string;
  /** The holding Job's Mac. Absent for a person in beads. */
  machine?: string;
  /** The holding Job's title. Absent for a person in beads, and for a Job with none. */
  title?: string;
  /**
   * Whether the holding Job is one of this Mac's, so its Mac is the one the person is on. Absent where it is
   * not, and for a person in beads. Since 14 Nov 2026.
   */
  this_mac?: boolean;
  /**
   * The holding Job's id on its Mac, which opens it where `this_mac`. Absent for a person in beads and
   * where main's own fix ends the wait. Since 14 Nov 2026.
   */
  job?: string;
  /** When the wait began. */
  since: Instant;
  /** What ends the wait. */
  ends: ClaimWaitEnds;
};

/** What ends a wait on a held item. Either way the Job is woken to carry on. */
export type ClaimWaitEnds =
  /** The other Job's claim ends: it closes the item, drops it, or its Mac stops renewing for 30 minutes. */
  | "claim_ends"
  /** The person is no longer the item's assignee in beads. */
  | "unassigned"
  /**
   * A failing test's fix merges and main is green, or main's own red is fixed: the pull request the
   * merge queue threw out is queued again. `item` is the test, and `holder` is empty while main is red.
   */
  | "fix_merges";

/** How a Job was started. Every part is absent where it was not set then. */
export type SessionStarted = {
  /** The workflow's name as it read then. */
  workflow?: string;
  /** The landing chosen by then. A Job that is asked later has none here. */
  delivery?: DeliveryChoice;
  /** The model it ran on, the machine's own where none was picked. */
  model?: string;
  effort?: string;
  mode?: SessionMode;
  /** The Job that started it. */
  by?: SessionLink;
};

/** The time a workflow step began. */
export type StepVisit = {
  /** The step's index in the workflow. */
  step: number;
  since: Instant;
};

/** A value of a Session the proposer can pick. */
export type ProposedField =
  | "title"
  | "workflow"
  | "model"
  | "effort";

/**
 * The proposer's part in a Session. **Per field, and cleared by the person's own change**: a
 * field in `picked` is a value the proposer chose and nobody has touched since, so Bridge marks
 * it "Picked by the proposer"; changing it in a panel takes it out of the list.
 */
export type SessionProposal = {
  /**
   * The call is out. The Session exists and its process has not started, and Fleet starts it on
   * the answer. Held in memory: a Fleet that restarts reads nothing as reading.
   */
  reading?: boolean;
  picked?: ProposedField[];
};
